out <- 'tmp/mixed-method-notes-i18n'; dir.create(out, recursive=TRUE, showWarnings=FALSE)
b <- list(effect_size_glmm_coefficient='-0.5', effect_size_glmm_binary_scale='coefficient', effect_size_glmm_count_scale='coefficient', effect_size_glmm_sd='2', effect_size_glmm_p1='.2', effect_size_glmm_p2='.4', effect_size_glmm_rate1='2', effect_size_glmm_rate2='4', effect_size_glmm_or='.5', effect_size_glmm_irr='.5')
l <- list(effect_size_lmm_design='glimmpse_vectors', effect_size_lmm_lmm_design='two_group_repeated', effect_size_lmm_group1_means='0, 0.2, 0.8', effect_size_lmm_group2_means='0, 0.1, 0.4', effect_size_lmm_residual_sd='1', effect_size_lmm_rho='.5', effect_size_lmm_correlation_structure='exchangeable')
glmm <- function(design, extra=list()) effect_size_glmm_calculate(modifyList(modifyList(b,list(effect_size_glmm_design=design)),extra))
designs <- c('continuous_d','binary_logit','binary_probabilities','count_log','count_rates','continuous_gaussian','glimmpse_vectors','logit_from_or','log_from_irr','one_group_vectors')
results <- c(list(effect_size_gee_calculate(list(effect_size_gee_design='continuous_d',effect_size_gee_d='-.5',effect_size_gee_sd_mode='direct',effect_size_gee_sd='1'))), lapply(designs[2:6],glmm), list(effect_size_lmm_calculate(l), glmm('binary_logit',list(effect_size_glmm_binary_scale='odds_ratio')), glmm('count_log',list(effect_size_glmm_count_scale='incidence_rate_ratio')), effect_size_lmm_calculate(modifyList(l,list(effect_size_lmm_lmm_design='one_group_repeated')))))
formula_keys <- paste0('sample_size.result.', c('note_gee_supplied','note_glmm_logit','note_glmm_probs','note_glmm_log','note_glmm_rates','note_glmm_identity','note_lmm_vectors','note_glmm_logit','note_glmm_log','note_lmm_vectors'))
for(i in seq_along(results)) stopifnot(is.null(results[[i]]$error), identical(results[[i]]$method_note,statedu_t(formula_keys[i],'en')))
expected <- c(-.5, exp(-.5), .375, exp(-.5), .5, -.25, -.4, .5, .5, .8)
for(i in seq_along(results)) stopifnot(isTRUE(all.equal(results[[i]]$primary_effect_size,expected[i])))
stopifnot(isTRUE(all.equal(results[[2]]$effect_size_d,-.5*sqrt(3)/pi)), isTRUE(all.equal(results[[3]]$cohens_h,2*asin(sqrt(.2))-2*asin(sqrt(.4)))), isTRUE(all.equal(results[[8]]$log_odds_ratio,log(.5))), isTRUE(all.equal(results[[9]]$log_incidence_rate_ratio,log(.5))), isTRUE(all.equal(results[[7]]$planning_effect_size,-.4*sqrt(3/2))), isTRUE(all.equal(results[[10]]$planning_effect_size,.8*sqrt(3/2))))
tokens <- list(character(),c('log(OR)','d = log(OR) * sqrt(3) / pi'),character(),c('log(IRR)','IRR = exp(B)'),'IRR','d = fixed-effect coefficient B / residual SD','GLIMMPSE')
for(lang in c('en','ko','ja','zh','es','fr','de','vi')) for(i in seq_along(tokens)) stopifnot(all(vapply(tokens[[i]],grepl,logical(1),x=statedu_t(formula_keys[i],lang),fixed=TRUE)))
cat('PASS ten actual GEE/GLMM/LMM cases and numeric references; seven method notes with eight-language expression preservation\n')
